"""Real local HTTP fixture; every model response is generated by a test double."""
import json
from pathlib import Path
import sys
import tempfile

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from liuyao_app.server import Application, Server
from liuyao_app import workbench


def answer(provider, model, prompt, payload, **options):
    if prompt == workbench.ISSUE_PROMPT:
        code = '报错' in payload['description']
        return {'parsed_json': {'category': 'code' if code else 'preferences',
                'summary': '需要修复程序。' if code else '缩短回答并解释术语。',
                'changes': {} if code else {'detail': 'concise', 'tone': 'beginner'},
                'acceptance': ['保留出处并回答所问。']}}
    return {'parsed_json': {'answer': '<b>原文回答</b>，已接续 ' + str(len(options.get('conversation_history', []))) + ' 条消息。' +
                ('已采用简洁偏好。' if '简洁回答' in prompt else ''),
                'citation_ids': [payload['sources'][0]['citation_id']], 'insufficient': False}}


if __name__ == '__main__':
    with tempfile.TemporaryDirectory() as directory:
        app = Application(directory)
        app.config = lambda: {'providers': [{'id': 'deepseek', 'name': '测试模型', 'models': ['test-model'],
            'default_model': 'test-model', 'configured': True}], 'default_provider': 'deepseek', 'storage_mode': 'local'}
        workbench.generate_json = answer
        server = Server(('127.0.0.1', 0), app)
        print(json.dumps({'url': 'http://127.0.0.1:' + str(server.server_port)}), flush=True)
        try:server.serve_forever(poll_interval=.02)
        finally:server.server_close();app.close()
